## (item 15) The lines the preview draws, as point pairs in rock space, every one cut to the stone: "edge" (the
## scar's outline where the crack comes out), "ring" (round the point; the small crush ring when `plan` is
## empty), "run" (down the face to where the crack comes out). The planned surface reaches past the stone
## (samples past its outline, the cutter's OUT), so a piece of a line over air is dropped (clip).
static func lines(cells: Array, plan: Dictionary, p: Vector3) -> Dictionary:
	if plan.is_empty():
		return {"edge": PackedVector3Array(), "run": PackedVector3Array(), "ring": clip(cells, ring_of(p, Vector3.UP, 0.02))}
	var run := PackedVector3Array()
	var steps := 8
	for i in steps:
		for j in 2:
			var xi := float(plan.L) * float(i + j) / steps
			run.append(Fracture._point(plan, 0.0, xi, Fracture._surf(plan, 0.0, xi) * smoothstep(0.0, 0.5 * float(plan.pt), xi)))
	return {"edge": clip(cells, Fracture.outline(plan)), "run": clip(cells, run),
		"ring": clip(cells, ring_of(p, plan.n, float(plan.a) + 0.01))}


## A ring of radius r round p (rock space) facing n, as point pairs.
static func ring_of(p: Vector3, n: Vector3, r: float) -> PackedVector3Array:
	var e1 := n.cross(Vector3.UP if absf(n.y) < 0.9 else Vector3.RIGHT).normalized()
	var e2 := n.cross(e1)
	var out := PackedVector3Array()
	for i in 16:
		for j in 2:
			var a := TAU * float(i + j) / 16.0
			out.append(p + (e1 * cos(a) + e2 * sin(a)) * r + n * 0.002)
	return out


const CLIP_STEP := 0.01          # m: a segment is tested every this far
const CLIP_TOL := 0.0025         # m: a point farther than this from the solid is in the air


## `pairs` (point pairs, rock space) with the parts over air cut off: each segment is walked in CLIP_STEP
## pieces and a piece stays when both its ends lie in the stone or within CLIP_TOL of it.
static func clip(cells: Array, pairs: PackedVector3Array) -> PackedVector3Array:
	var out := PackedVector3Array()
	for i in range(0, pairs.size() - 1, 2):
		var a := pairs[i]
		var b := pairs[i + 1]
		var n := maxi(ceili(a.distance_to(b) / CLIP_STEP), 1)
		var prev := a
		var prev_ok := solid_near(cells, a)
		for k in range(1, n + 1):
			var q := a.lerp(b, float(k) / n)
			var ok := solid_near(cells, q)
			if prev_ok and ok:
				out.append(prev)
				out.append(q)
			prev = q
			prev_ok = ok
	return out


## Point q (rock space) in the solid of `cells` or within CLIP_TOL of it (probes along the axes).
static func solid_near(cells: Array, q: Vector3) -> bool:
	if not RockNode.near_cells(cells, q, CLIP_TOL):
		return false
	if RockNode.inside(cells, q):
		return true
	for d: Vector3 in AXES:
		if RockNode.inside(cells, q + d * CLIP_TOL):
			return true
	return false


const AXES: Array[Vector3] = [Vector3.RIGHT, Vector3.LEFT, Vector3.UP, Vector3.DOWN, Vector3.BACK, Vector3.FORWARD]
'''
